rec(id='P1', nombre='Lemon-Garlic Sheet-Pan Chicken Thighs', comp='proteina', fam=['MEX','ASI','MED','COM'],
 yld=680, ing=[('thigh','2 lb',907),('oil','2 tbsp',27),('lemon','3 tbsp',45),('garlic','4 cloves, minced',12),('oregano','1 tsp',1.5),('paprika','1 tsp',2.5),('salt','1 tsp',6),('pepperb','1/2 tsp',1)],
 alerg=[], fr=4, fz=3, reheat='Microwave 60-90 sec, covered, until steaming hot (165 °F / 74 °C).', act=10, tot=40, oven=(220,425), slot='Oven',
 slot_txt='Oven, minute 0. Goes in first, comes out at minute 25-28, then rests while you fill the oven with the next tray.',
 steps=['Heat the oven to 425 °F / 220 °C. Line a rimmed sheet pan with parchment.',
  'Whisk the oil, lemon juice, garlic, oregano, paprika, salt and pepper in a large bowl. Add the thighs and toss until every piece is coated. Leave 10 minutes, or up to 8 hours in the fridge.',
  'Spread the thighs in one layer with space between them. Do not stack.',
  'Roast 22-28 minutes. Done when the edges are browned, the juices run clear and a thermometer in the thickest piece reads 165 °F / 74 °C.',
  'Rest 5 minutes on the pan. Slice into strips or bite-size pieces.',
  'Portion into 5 containers (about 135 g each). Cool for up to 1 hour at room temperature, then refrigerate.'],
 fix=['Pale and wet instead of browned: the pan was crowded or the oven was cool. Put it back 5 minutes under the broiler, watching it closely.','Dry? Thighs forgive, but if they went past 185 °F, toss the slices with a spoon of the pan juices before storing.'],
 swap='Use bone-in thighs (about 2.75 lb, add 10 minutes) or chicken breast cut into 1-inch strips (cook 15-18 minutes). For no lemon, use 1 tbsp red wine vinegar.')

rec(id='P2', nombre='Slow-Cooker Salsa Shredded Chicken', comp='proteina', fam=['MEX','COM'],
 yld=700, ing=[('breast','2.2 lb',1000),('salsa','1 1/2 cups (1 jar, 16 oz)',360),('cumin','2 tsp',4),('chili','2 tsp',5),('garlicp','1 tsp',3),('salt','1 tsp',6),('lime','2 tbsp',30)],
 alerg=[], fr=4, fz=3, reheat='Microwave 90 sec with 1 tbsp of its cooking juices, stir halfway, until steaming hot (165 °F / 74 °C).', act=10, tot=250, oven=None, slot='Slow cooker',
 slot_txt='Slow cooker, minute 0. It works alone for 3-4 hours on HIGH, so start it before anything else. It never touches the oven or the stove.',
 steps=['Lay the chicken breasts in the slow cooker in one layer if you can. Sprinkle with cumin, chili powder, garlic powder and salt.',
  'Pour the salsa over the top. Do not add water: the chicken gives off its own liquid.',
  'Cover. Cook on LOW 6-7 hours or HIGH 3-4 hours. Done when a thermometer in the thickest breast reads 165 °F / 74 °C and a fork shreds it with no effort.',
  'Move the chicken to a bowl. Shred with two forks or by beating it 20 seconds with a hand mixer.',
  'Stir in the lime juice and 1/2 cup of the cooking liquid. Taste and add a pinch of salt if needed.',
  'Portion into 5 containers (about 140 g each) with a spoonful of juices on each so it stays moist.'],
 fix=['Watery? Simmer the leftover liquid 5 minutes in a pan, or just use less when mixing back in.','Stringy and dry: it cooked too long on HIGH. Next time check at 3 hours, and always mix the juices back in.'],
 swap='Use boneless thighs (same weight, shred more tender) or a green salsa (tomatillo) for a milder, tangy version. Low on money: bone-in breasts, 3 lb, shredded after cooking.')

rec(id='P3', nombre='Never-Dry Baked Chicken Breast', comp='proteina', fam=['MEX','ASI','MED','COM'],
 yld=750, ing=[('breast','2.2 lb',1000),('oil','1 tbsp',14),('salt','1 tsp',6),('pepperb','1/2 tsp',1),('garlicp','1 tsp',3),('paprika','1 tsp',2.5)],
 alerg=[], fr=4, fz=3, reheat='Microwave at 70% power for 60-90 sec, or slice and warm in a covered pan with a splash of water. Never full power for long.', act=10, tot=45, oven=(220,425), slot='Oven',
 slot_txt='Oven, minute 0 to 25. Can share the oven with a veg tray at the same 425 °F / 220 °C.',
 steps=['Salt the chicken (the 1 tsp) on both sides 15-30 minutes before cooking, or overnight in the fridge. This is a dry brine.',
  'Heat the oven to 425 °F / 220 °C. Place a chicken breast between plastic wrap or in a bag and pound the thick end with a pan or rolling pin until it is an even 3/4 inch / 2 cm thick. Do all breasts.',
  'Rub with the oil, then the pepper, garlic powder and paprika. Lay on a lined sheet pan, with space between them.',
  'Bake 16-20 minutes. Start checking at 14. Done when a thermometer in the thickest part reads 160 °F / 71 °C, then it carries up to 165 °F / 74 °C as it rests.',
  'Rest covered with foil for 5-10 minutes. Cutting early lets the juices run out.',
  'Slice against the grain. Portion into 5 containers (150 g each) and drizzle any pan juices on top.'],
 fix=['Rubbery or dry: it went past 165 °F or the breasts were uneven. Pound them flat next time and use the thermometer, not the clock.','White and wet on the surface: pat the chicken dry before the oil goes on.'],
 swap='Use thin-sliced breast cutlets (bake 10-12 minutes) to save pounding. Swap the spices for 2 tsp Italian seasoning or taco seasoning for a different family.')

rec(id='P4', nombre='Turkey Taco Crumble', comp='proteina', fam=['MEX'],
 yld=700, ing=[('turkey93','2 lb',907),('onion','1 medium, finely diced',150),('garlic','3 cloves, minced',9),('oil','1 tbsp',14),('tomatopaste','2 tbsp',32),('chili','2 tbsp',16),('cumin','2 tsp',4),('paprika','1 tsp',2.5),('oregano','1 tsp',1.5),('salt','1 1/2 tsp',9)],
 alerg=[], fr=4, fz=3, reheat='Microwave 90 sec, stirring halfway, until steaming hot (165 °F / 74 °C).', act=20, tot=25, oven=None, slot='Stovetop',
 slot_txt='Stovetop, one large skillet, minute 0 to 20. Frees the pan for a second batch of anything.',
 steps=['Heat the oil in a large skillet over medium heat. Add the onion and a pinch of salt. Cook 4-5 minutes until soft and see-through.',
  'Add the garlic, chili powder, cumin, paprika and oregano. Stir 30 seconds until it smells toasty.',
  'Add the turkey. Break it up with a wooden spoon or a potato masher. Cook 7-9 minutes until no pink is left and it reaches 165 °F / 74 °C (ground turkey is safe at 165 °F).',
  'Stir in the tomato paste, the salt and 1/2 cup water. Simmer 3-4 minutes until the liquid has mostly cooked off and the meat looks glossy, not soupy.',
  'Cool for 20 minutes, spread out in a wide dish. Portion into 5 containers (about 140 g each).'],
 fix=['Dry and crumbly: add 2-3 tbsp water and simmer 1 minute, then do the same when you reheat.','Bland: more salt and a squeeze of lime at reheat. Turkey needs more salt than beef.'],
 swap='Use 93% lean ground chicken (same weight) or ground beef (90%, adds fat and a little protein). Out of chili powder: 1 tbsp taco seasoning replaces the three spices.')

rec(id='P5', nombre='Beef & Lentil Power Mince', comp='proteina', fam=['MEX','MED','COM'],
 yld=800, ing=[('beef90','1 lb',454),('lentil','3/4 cup (150 g)',150),('onion','1 medium, diced',150),('carrot','1 large, finely diced',100),('garlic','3 cloves, minced',9),('oil','1 tbsp',14),('tomatopaste','2 tbsp',32),('cumin','2 tsp',4),('paprika','2 tsp',5),('chili','1 tsp',2.7),('salt','1 1/2 tsp',9)],
 alerg=[], fr=4, fz=3, reheat='Microwave 90 sec, stirring halfway, until steaming hot (165 °F / 74 °C).', act=20, tot=50, oven=None, slot='Stovetop',
 slot_txt='Stovetop, minute 0 to 45, one pot. Lentils simmer while you chop the rest. Lowest-cost protein of the book: 1 lb of beef covers 5 portions.',
 steps=['Rinse the lentils in a sieve and pick out any stones.',
  'Heat the oil in a large pot over medium-high. Add the beef and break it up. Cook 6-8 minutes until browned and no pink is left (160 °F / 71 °C).',
  'Add the onion and carrot. Cook 5 minutes until the onion is soft.',
  'Add the garlic, tomato paste and spices. Stir 1 minute until the paste darkens a shade.',
  'Add the lentils, the salt and 3 cups water. Bring to a boil, then lower to a steady simmer, partly covered.',
  'Cook 22-28 minutes, stirring now and then. Done when the lentils are tender but not mushy and the pot is thick like chili, with almost no loose liquid. Add water 1/4 cup at a time if it dries too soon.',
  'Cool, then portion into 5 containers (about 160 g each).'],
 fix=['Hard lentils after 30 minutes: old lentils. Add 1/2 cup water and simmer 10 more minutes.','Too wet: simmer uncovered 5 minutes. Too thick on day 3: loosen with a splash of water.'],
 swap='Use ground turkey in place of beef, or half the beef and a second 1/2 cup of lentils for the cheapest week. Red lentils cook in 12 minutes but go soft.')

rec(id='P6', nombre='Freezer Turkey Meatballs', comp='proteina', fam=['MED','COM','ASI'],
 yld=780, ing=[('turkey93','2 lb',907),('egg','1 large',50),('crumbs','1/2 cup',55),('parm','1/4 cup (about 1 oz)',28),('garlic','3 cloves, minced',9),('onionp','1 tsp',2.5),('oregano','1 tsp',1.5),('parsley','2 tbsp, chopped',8),('salt','1 1/2 tsp',9),('pepperb','1/2 tsp',1)],
 alerg=['milk','egg','wheat'], fr=4, fz=3, reheat='Microwave 6 meatballs 60-90 sec, or 12 min at 350 °F / 175 °C from frozen, until 165 °F / 74 °C in the centre.', act=15, tot=35, oven=(205,400), slot='Oven',
 slot_txt='Oven, minute 0 to 25. Freezer champion: double the batch and freeze the second half flat on a tray, then bag.',
 steps=['Heat the oven to 400 °F / 205 °C. Line a rimmed sheet pan with parchment.',
  'In a large bowl, mix the egg, breadcrumbs, Parmesan, garlic, onion powder, oregano, parsley, salt and pepper. Let it sit 3 minutes so the crumbs soak up the egg.',
  'Add the turkey. Mix with your hands only until it just comes together. Overmixing makes them tough.',
  'Scoop 30 even balls (about 2 tbsp each, a bit over 1 oz / 35 g) and roll them smooth. Wet your hands if it sticks.',
  'Place on the pan, close but not touching. Bake 18-20 minutes. Done when browned on top and a thermometer in the middle reads 165 °F / 74 °C.',
  'Cool 15 minutes. Portion 6 meatballs per container (about 155 g). To freeze, lay on a tray for 1 hour, then bag.'],
 fix=['Dry meatballs: you overmixed, or baked past 165 °F. Reheat them in a covered pan with a spoonful of sauce.','Falling apart: the mix was too wet. Add 1 more tbsp breadcrumbs and chill 10 minutes.'],
 swap='Gluten-free: swap the breadcrumbs for 1/2 cup rolled oats pulsed fine. Dairy-free: leave out the Parmesan and add 1/4 tsp more salt. Ground chicken works too.')

rec(id='P7', nombre='Oven Pulled Pork Shoulder', comp='proteina', fam=['MEX','COM','ASI'],
 yld=780, ing=[('pork','3 lb, after trimming (buy about 3 3/4 lb)',1361),('brownsugar','1 tbsp',13),('paprika','1 tbsp',7),('cumin','2 tsp',4),('garlicp','2 tsp',6),('salt','2 1/2 tsp',15),('pepperb','1 tsp',2),('cidervin','1/4 cup',58)],
 alerg=[], fr=4, fz=3, reheat='Microwave 90 sec with 1 tbsp of its juices until steaming hot (165 °F / 74 °C).', act=15, tot=300, oven=(150,300), slot='Oven',
 slot_txt='Oven, minute 0 to 270. Start it first. At 300 °F it blocks the oven for 4-4.5 hours, so P7 is a slow-Sunday protein: pair it with stovetop bases and cold veg, or cook it Saturday and shred on Sunday.',
 steps=['Heat the oven to 300 °F / 150 °C. Trim off the thick fat cap and any big fat seams you can reach with a knife (the macros here are for trimmed meat). Mix the sugar, paprika, cumin, garlic powder, salt and pepper. Rub it all over the pork.',
  'Place the pork in a Dutch oven or a deep baking dish. Pour in the vinegar and 1/2 cup water around it, not over it.',
  'Cover tightly with a lid or double foil. Roast 4 to 4 1/2 hours.',
  'Done when a thermometer reads 195-205 °F / 90-96 °C and a fork twists in with no resistance. Safe at 145 °F, but it only shreds once the connective tissue melts at the higher temperature.',
  'Rest 20 minutes, covered. Move to a board. Discard any bone and leftover fat. Shred with two forks.',
  'Skim the fat from the pan juices. Toss the pork with 1/2 cup of the juices. Portion into 5 containers (about 155 g each).'],
 fix=['Pork will not shred: it needs more time. Re-cover and give it another 30-45 minutes.','Dry after reheating: always store with its juices; add 1 tbsp water to the container before the microwave.'],
 swap='Same recipe in a slow cooker: LOW 8-10 hours, no extra liquid except the vinegar. Leaner and faster: use pork tenderloin (cook to 145 °F), but it will not be as juicy.')

rec(id='P8', nombre='Simple Baked Salmon', comp='proteina', fam=['MEX','ASI','MED','COM'],
 yld=730, ing=[('salmon','2 lb (skin-off or skin-on)',907),('oil','1 tbsp',14),('lemon','1 tbsp',15),('garlicp','1 tsp',3),('paprika','1 tsp',2.5),('salt','3/4 tsp',4.5),('pepperb','1/4 tsp',0.5)],
 alerg=['fish'], fr=3, fz=2, reheat='Eat cold, or microwave at 50% power 60-90 sec. Do not boil it; it dries and smells.', act=8, tot=22, oven=(205,400), slot='Oven',
 slot_txt='Oven, minute 0 to 15. Quick tray: put it in last if the oven is busy, but eat it on days 1-2 of the week for best quality.',
 steps=['Heat the oven to 400 °F / 205 °C. Line a sheet pan with parchment.',
  'Pat the salmon dry. Cut into 5 even portions (about 180 g raw each).',
  'Place on the pan, skin side down. Rub with the oil, lemon juice, garlic powder, paprika, salt and pepper.',
  'Bake 11-14 minutes. Done when the thickest part flakes with a fork and reads 145 °F / 63 °C. It should look opaque with a slight shine inside, not dry and chalky.',
  'Rest 3 minutes. Cool for up to 1 hour at room temperature, then refrigerate in a sealed container.'],
 fix=['White liquid on top (albumin): you cooked it hot and fast. Lower to 375 °F and shorten the time next batch.','Smells fishy on day 4: it is past its best. Plan this protein for the first 2 days and freeze the rest the same day.'],
 swap='Use arctic char or steelhead trout (same weight). For a budget version, use canned salmon (14.75 oz cans) mixed with lemon, but the macros change.')

rec(id='P9', nombre='Crispy Baked Tofu', comp='proteina', fam=['ASI','MEX','MED'],
 yld=680, ing=[('tofu','2 blocks (16 oz / 454 g each), extra-firm',908),('cornstarch','3 tbsp',24),('soy','3 tbsp',48),('oil','2 tbsp',27),('garlicp','1 tsp',3),('paprika','1 tsp',2.5),('pepperb','1/2 tsp',1)],
 alerg=['soy','wheat'], fr=4, fz=2, reheat='Oven or air fryer, 400 °F / 205 °C for 6-8 minutes to bring back the crisp. Microwave makes it soft.', act=15, tot=55, oven=(220,425), slot='Oven',
 slot_txt='Oven, minute 0 to 35 (after a 20-minute press that happens while you prep everything else).',
 steps=['Drain the tofu. Wrap in clean towels, set a heavy pan on top and press 20 minutes.',
  'Heat the oven to 425 °F / 220 °C. Line a sheet pan with parchment.',
  'Tear or cut the tofu into 3/4-inch / 2 cm cubes. Toss gently with the soy sauce and oil, then the garlic powder, paprika and pepper.',
  'Sprinkle on the cornstarch and toss until the pieces look dry and lightly coated, with no white clumps.',
  'Spread in one layer with space between pieces. Bake 15 minutes, flip, bake 15-18 minutes more.',
  'Done when the outside is golden and firm, and a cube sounds hollow when you tap it. It crisps more as it cools. Portion into 5 containers (about 135 g each).'],
 fix=['Soft, not crispy: not pressed enough, or the pan was crowded. Pat dry harder and use two pans.','Stuck to the pan: the parchment was missing or you flipped too soon. Wait until the edge lifts easily.'],
 swap='Gluten-free: use tamari (check the label) instead of soy sauce. Use baked tempeh cubes for more protein per portion, or pressed cubes of extra-firm tofu with 1 tbsp more oil in an air fryer.')

rec(id='P10', nombre='Smoky Spiced Chickpeas', comp='proteina', fam=['MED','MEX'],
 yld=700, ing=[('chickpea','3 cans (15 oz), drained and rinsed',750),('oil','2 tbsp',27),('paprika','2 tsp',5),('cumin','1 tsp',2),('garlicp','1 tsp',3),('salt','1 tsp',6),('lemon','1 tbsp',15)],
 alerg=[], fr=4, fz=2, reheat='Microwave 60 sec, or 5 minutes in a hot oven or air fryer to bring back the edges.', act=8, tot=35, oven=(220,425), slot='Oven',
 slot_txt='Oven, minute 0 to 30. Cheapest protein in the book, and the only plant protein P with no pressing or soaking.',
 steps=['Heat the oven to 425 °F / 220 °C.',
  'Drain and rinse the chickpeas. Spread on a towel and pat very dry. Dry beans roast. Wet beans steam.',
  'Toss on a sheet pan with the oil, paprika, cumin, garlic powder and salt.',
  'Roast 25-30 minutes, shaking the pan once at the halfway point. Done when the chickpeas are golden, shrunken a little and the skins split.',
  'Toss with the lemon juice right out of the oven.',
  'Cool, then portion into 5 containers (about 140 g each).'],
 fix=['Soft in the fridge: normal, they take on moisture. Re-crisp them 5 minutes in the oven or air fryer.','Burnt spice on the pan: the oven was too hot or the pan was dark. Lower to 400 °F / 205 °C and use parchment.'],
 swap='Use white beans or black beans (canned, rinsed). Skip the smoke with 2 tsp Italian seasoning for a Mediterranean version. Each portion has about 11 g of protein, about a third of the chicken recipes: pair it with a higher-protein sauce like Greek yogurt.')

rec(id='B1', nombre='Hands-Off Oven Rice', comp='base', fam=['MEX','ASI','MED','COM'],
 yld=800, ing=[('rice','1 1/2 cups',278),('oil','1 tbsp',14),('salt','1 tsp',6)],
 alerg=[], fr=4, fz=2, reheat='Microwave 90 sec with 1 tbsp of water, covered, until steaming hot (165 °F / 74 °C).', act=5, tot=45, oven=(190,375), slot='Oven',
 slot_txt='Oven, minute 0 to 30, then rest 10 minutes off. Fits next to a 425 °F tray if you cover it well; or cook it before the high-heat trays.',
 steps=['Heat the oven to 375 °F / 190 °C. Boil 2 1/4 cups of water in a kettle or pot.',
  'Rinse the rice in a sieve under cold water for 30 seconds. Drain well.',
  'Put the rice, oil and salt in an 8x8-inch / 20 cm baking dish (or any dish with a tight lid). Pour in the boiling water and stir once.',
  'Cover tightly with foil, crimping all the edges. Bake 25-30 minutes without opening it.',
  'Done when all the water is absorbed and small steam holes show on the surface. Leave covered 10 minutes, then fluff with a fork.',
  'Spread the rice out in a thin layer to cool, then portion into 5 containers (160 g each) within 1 hour of cooking. Refrigerate right away.'],
 fix=['Crunchy grains: the foil leaked steam. Add 2 tbsp hot water, re-cover and give it 10 minutes.','Gummy: too much water or no rinse. Spread on a pan and dry 5 minutes in the oven.'],
 swap='Brown rice: use 1 1/2 cups rice and 2 3/4 cups boiling water, bake 55-60 minutes. Cauliflower rice is not a swap in this recipe (it does not bake like rice).')

rec(id='B2', nombre='Fluffy Quinoa', comp='base', fam=['ASI','MED','MEX','COM'],
 yld=840, ing=[('quinoa','1 1/2 cups',255),('oil','1 tbsp',14),('salt','3/4 tsp',4.5)],
 alerg=[], fr=4, fz=3, reheat='Microwave 60-90 sec with a splash of water, covered, until steaming hot (165 °F / 74 °C).', act=5, tot=25, oven=None, slot='Stovetop',
 slot_txt='Stovetop, minute 0 to 20, one pot with a lid. Hands free after the first 5 minutes.',
 steps=['Rinse the quinoa in a fine sieve for 30 seconds, rubbing it with your hand. This removes the bitter coating.',
  'Add the quinoa, 3 cups water, oil and salt to a medium pot. Bring to a boil.',
  'Lower to the lowest heat, cover and cook 14-16 minutes. Done when the water is gone and you can see the little white spiral tails on each seed.',
  'Take off the heat, keep the lid on and leave 5 minutes. Fluff with a fork.',
  'Spread on a tray to cool 15 minutes. Portion into 5 containers (about 165 g each) and refrigerate within 1 hour.'],
 fix=['Mushy: too much water or you lifted the lid. Next time stick to 2 cups of water per 1 cup of quinoa.','Bitter: it was not rinsed enough.'],
 swap='Use millet or couscous in the same weight if quinoa is too pricey. Cheaper: half quinoa, half rice, cooked separately.')

rec(id='B3', nombre='Crispy Roasted Baby Potatoes', comp='base', fam=['MEX','MED','COM'],
 yld=850, ing=[('redpot','2.2 lb baby red potatoes, halved',1000),('oil','2 tbsp',27),('salt','1 tsp',6),('garlicp','1 tsp',3),('paprika','1 tsp',2.5),('pepperb','1/2 tsp',1)],
 alerg=[], fr=4, fz=0, reheat='Oven or air fryer, 400 °F / 205 °C for 8-10 minutes. Microwave makes them soft.', act=10, tot=45, oven=(220,425), slot='Oven',
 slot_txt='Oven, minute 0 to 40 (long tray, so put it in first). Goes on the lower rack at 425 °F / 220 °C.',
 steps=['Heat the oven to 425 °F / 220 °C. Put the empty sheet pan in the oven to heat.',
  'Halve the potatoes (quarter any bigger than a golf ball). Dry them with a towel.',
  'Toss in a bowl with the oil, salt, garlic powder, paprika and pepper.',
  'Carefully tip onto the hot pan, cut sides down. They should sizzle.',
  'Roast 20 minutes, flip, then roast 15-20 minutes more. Done when the cut sides are deep golden and a knife slides in with no push.',
  'Cool, then portion into 5 containers (about 170 g each).'],
 fix=['Soggy: they were wet or the pan was crowded. Dry them and use two pans.','Hard centres, burnt edges: pieces were uneven. Cut to the same size, and give the big ones 10 minutes extra.'],
 swap='Use Yukon Gold potatoes cut into 1-inch chunks. Not good for the freezer: they turn grainy and watery.')

rec(id='B4', nombre='Roasted Sweet Potato Cubes', comp='base', fam=['MEX','ASI','COM'],
 yld=850, ing=[('sweetpot','2.2 lb (about 3 medium), peeled, 3/4-inch cubes',1000),('oil','2 tbsp',27),('salt','1 tsp',6),('paprika','1 tsp',2.5),('pepperb','1/2 tsp',1)],
 alerg=[], fr=4, fz=3, reheat='Microwave 60-90 sec, covered, or 8 minutes in a 400 °F / 205 °C oven to re-crisp.', act=15, tot=45, oven=(220,425), slot='Oven',
 slot_txt='Oven, minute 0 to 35. Needs one flip. Works on the same rack as other 425 °F trays.',
 steps=['Heat the oven to 425 °F / 220 °C. Line a pan with parchment.',
  'Peel the sweet potatoes and cut into 3/4-inch / 2 cm cubes. Keep them the same size so they cook evenly.',
  'Toss with the oil, salt, paprika and pepper. Spread in one layer, not touching.',
  'Roast 15 minutes, flip, then roast 12-15 minutes more.',
  'Done when the edges are browned and caramelised, and a fork slides into the centre with no resistance.',
  'Cool, then portion into 5 containers (about 170 g each).'],
 fix=['Soft and no browning: the pan was crowded. Use two pans or reduce to a single layer.','Burnt edges, hard middle: cubes too large. Next time cut to 3/4 inch.'],
 swap='Butternut squash cubes work in the same time. For a sweeter finish, add 1/2 tsp cinnamon in place of the paprika.')

rec(id='B5', nombre='Reheat-Ready Pasta', comp='base', fam=['COM','ASI','MED'],
 yld=750, ing=[('pasta','12 oz (340 g) penne or fusilli',340),('oil','1 tbsp',14),('salt','1 tbsp (for the water; only part is absorbed)',6)],
 alerg=['wheat'], fr=4, fz=2, reheat='Microwave 60-90 sec with 1 tbsp of water or sauce, covered, until steaming hot (165 °F / 74 °C).', act=5, tot=20, oven=None, slot='Stovetop',
 slot_txt='Stovetop, minute 0 to 15 while the oven trays roast. Boil the water first thing so it is ready.',
 steps=['Bring 3 quarts / 3 L of water to a rolling boil. Add the salt.',
  'Add the pasta. Cook 1-2 minutes LESS than the package says. It must still have a firm centre, since it cooks more when you reheat it.',
  'Check by biting a piece: you should see a thin white dot in the centre.',
  'Drain. Do not rinse. Toss right away with the oil so the pieces do not stick together.',
  'Spread on a tray to cool 15 minutes. Portion into 5 containers (about 150 g each).'],
 fix=['Clumped together in the fridge: not enough oil. Add a splash of water on reheat and break up with a fork.','Mushy after reheating: it was overcooked to start with. Pull it 2 minutes early next time.'],
 swap='Gluten-free: use a corn-and-rice pasta and cook 2 minutes less. Higher protein: use chickpea or lentil pasta (this changes the macros, recalculate).')

rec(id='B6', nombre='Wraps & Tortillas (Store & Assemble)', comp='base', fam=['MEX','MED','COM'],
 yld=250, ing=[('tortilla','5 flour tortillas, 8-inch',250)],
 alerg=['wheat'], fr=7, fz=2, reheat='Warm 15 seconds per side in a dry pan, or 10 seconds in the microwave wrapped in a damp towel. Assemble the wrap at lunch.', act=5, tot=5, oven=None, slot='Cold',
 slot_txt='No cooking at all. Minute 0: portion and wrap. Do this while the oven works.',
 steps=['Check the date on the package. Keep the tortillas in the fridge once opened.',
  'Stack the tortillas in two groups, with a square of parchment between each.',
  'Slide them into a zip bag and press out the air. For 5 days, one bag is enough.',
  'To freeze beyond a week: wrap in foil, then a freezer bag. Defrost overnight in the fridge.',
  'Assemble the wrap on the day. Warm the tortilla, then fill with 1 protein portion, a vegetable portion and a spoonful of sauce, and fold in the sides before rolling.',
  'For a lunch you take with you: pack the filling in a container and the tortilla in a bag, and assemble at lunch to avoid sogginess.'],
 fix=['Cracks when you fold it: it is cold or dry. Warm 15 seconds in a dry pan to make it bendable.','Soggy by lunch: the filling was wet. Keep sauce in its own cup and add it at the last minute.'],
 swap='Use corn tortillas (6-inch, 2 per portion) for gluten-free tacos, or low-carb wraps, but check the label. Check macros for any wrap that is not plain flour.')

rec(id='V1', nombre='Charred Roasted Broccoli', comp='verdura', fam=['MEX','ASI','MED','COM'],
 yld=650, ing=[('broccoli','2 large crowns (about 2 lb), cut into florets',900),('oil','2 tbsp',27),('salt','1 tsp',6),('garlicp','1 tsp',3)],
 alerg=[], fr=4, fz=0, reheat='Eat cold in bowls, or 10 minutes in a hot oven or air fryer. Microwave makes it soft but it is safe.', act=10, tot=30, oven=(230,450), slot='Oven',
 slot_txt='Oven, minute 0 to 22 at 450 °F / 230 °C. Hottest tray of the day. Do it first, then lower the oven for the rest.',
 steps=['Heat the oven to 450 °F / 230 °C.',
  'Cut the broccoli into bite-size florets, with a flat cut side if possible. Cut thick stems into coins.',
  'Dry well. Toss with the oil, salt and garlic powder.',
  'Spread over a large pan with space between pieces. Place cut sides down.',
  'Roast 18-22 minutes without stirring more than once. Done when the tips are blackened in spots, the stems pierce with a knife, and the florets look dark green and slightly shrunken.',
  'Portion into 5 containers (about 130 g each).'],
 fix=['Limp and olive-colored: too wet, too crowded or too low an oven. Dry it and use 2 pans.','Bitter, burnt tips: oven too hot or pan too close to the top. Lower the rack.'],
 swap='Use cauliflower (same time) or Brussels sprouts halved (add 5 minutes). Frozen broccoli: roast from frozen at 450 °F for 25 minutes, less crisp.')

rec(id='V2', nombre='Sheet-Pan Fajita Peppers & Onions', comp='verdura', fam=['MEX'],
 yld=650, ing=[('pepper','3 bell peppers (red, green or mix), sliced',600),('onion','2 medium, sliced in 1/2-inch strips',300),('oil','2 tbsp',27),('chili','2 tsp',5),('cumin','1 tsp',2),('garlicp','1 tsp',3),('salt','1 tsp',6),('lime','1 tbsp',15)],
 alerg=[], fr=4, fz=3, reheat='Microwave 60 sec, or a hot dry pan for 3 minutes for better texture.', act=10, tot=35, oven=(220,425), slot='Oven',
 slot_txt='Oven, minute 0 to 28 at 425 °F / 220 °C. Shares the oven with P1, P3, P9 and P10.',
 steps=['Heat the oven to 425 °F / 220 °C.',
  'Slice the peppers and onions into strips about 1/2 inch / 1 cm wide, all the same size.',
  'Toss with the oil, chili powder, cumin, garlic powder and salt.',
  'Spread over a large pan in one layer. Do not crowd.',
  'Roast 25-28 minutes, stirring once at 15 minutes. Done when the onions are soft and golden at the edges and the peppers have blistered spots.',
  'Squeeze the lime juice on top. Portion into 5 containers (about 130 g each).'],
 fix=['Watery: the pan was too crowded. Use 2 pans or drain the liquid before storing.','Too crunchy: slice them thinner next time and leave 5 more minutes.'],
 swap='Add 1 sliced poblano or a jalapeno for heat. If peppers are expensive, use half peppers and half zucchini.')

rec(id='V3', nombre='Roasted Zucchini & Red Onion', comp='verdura', fam=['MEX','MED','COM'],
 yld=650, ing=[('zucchini','3 medium (about 1.7 lb), cut in 1/2-inch half-moons',750),('redonion','1 large red onion, cut in wedges',200),('oil','2 tbsp',27),('oregano','1 tsp',1.5),('garlicp','1/2 tsp',1.5),('salt','1 tsp',6),('lemon','1 tbsp',15)],
 alerg=[], fr=3, fz=0, reheat='Eat cold, or microwave 45 sec. Best on the first 3 days; it gets watery after.', act=10, tot=30, oven=(220,425), slot='Oven',
 slot_txt='Oven, minute 0 to 25 at 425 °F / 220 °C. Zucchini goes in last in the week-1 order, as it turns watery the longest in the fridge.',
 steps=['Heat the oven to 425 °F / 220 °C.',
  'Cut the zucchini in 1/2-inch half-moons. Cut the onion into thick wedges, keeping the root so the layers hold together.',
  'Toss with the oil, oregano, garlic powder and salt.',
  'Spread over a large pan in one layer. Zucchini likes space and high heat.',
  'Roast 20-25 minutes, turning once at 12 minutes. Done when the edges are golden brown and the middle is tender, not soft and mushy.',
  'Add the lemon juice. Portion into 5 containers (about 130 g each).'],
 fix=['Mushy and wet: pan crowded or pieces too thin. Next time keep them thick and use 2 pans.','Watery by day 3: normal. Pat dry with a paper towel before eating.'],
 swap='Use yellow squash, or eggplant cubes (add 5 minutes). Add 1/2 tsp of smoked paprika for a stronger taste.')

rec(id='V4', nombre='Garlic Green Beans', comp='verdura', fam=['ASI','MED','COM'],
 yld=600, ing=[('greenbean','1.5 lb, trimmed',700),('oil','2 tbsp',27),('garlic','4 cloves, minced',12),('salt','3/4 tsp',4.5),('pepperb','1/4 tsp',0.5),('lemon','1 tbsp',15)],
 alerg=[], fr=4, fz=0, reheat='Eat cold in bowls, or microwave 45-60 sec.', act=10, tot=25, oven=(220,425), slot='Oven',
 slot_txt='Oven, minute 0 to 18 at 425 °F / 220 °C. The garlic goes on in the last 5 minutes.',
 steps=['Heat the oven to 425 °F / 220 °C.',
  'Trim the ends off the green beans. Dry them well.',
  'Toss with the oil, salt and pepper. Spread in one layer on a large pan.',
  'Roast 10-12 minutes until they start to wrinkle.',
  'Take out, scatter the garlic over, stir, and roast 4-6 minutes more. Done when the beans are wrinkled with brown spots and still have a little snap, and the garlic is pale gold, not dark.',
  'Add the lemon juice. Portion into 5 containers (about 120 g each).'],
 fix=['Bitter garlic: it burned. Always add it late, and take it out when pale gold.','Limp beans: roasted too long or too low. Next time use the top rack and check at 12 minutes.'],
 swap='Use asparagus (cook 8-10 minutes) or snap peas (7-9 minutes). Frozen green beans work: roast from frozen for 20 minutes.')

rec(id='V5', nombre='Sesame Cabbage-Carrot Slaw (raw)', comp='verdura', fam=['ASI','MEX','COM'],
 yld=650, ing=[('cabbage','1/2 small head (about 1 lb), thinly shredded',450),('carrot','2 large, grated',150),('scallion','3, thinly sliced',40),('sesoil','1 tbsp',14),('canola','1 tbsp',14),('cidervin','3 tbsp',45),('soy','1 tbsp',16),('honey','1 tbsp',21),('sesame','1 tbsp',9),('ginger','1/2 tsp',1)],
 alerg=['sesame','soy','wheat'], fr=4, fz=0, reheat='Not reheated. Eat cold. Keep the dressing in a jar and toss on the day for crunch.', act=15, tot=15, oven=None, slot='Cold',
 slot_txt='Cold prep, no heat. Do it while the oven runs. Dress it only on days 1-2 if you want maximum crunch.',
 steps=['Shred the cabbage as thin as you can with a sharp knife. Grate the carrots. Slice the scallions.',
  'In a jar or bowl, whisk the sesame oil, canola oil, vinegar, soy sauce, honey, ginger and half the sesame seeds until the honey dissolves.',
  'Combine the vegetables in a big bowl. Keep the dressing apart for now.',
  'Portion the vegetables into 5 containers (about 130 g each) with a small cup or section for the dressing (about 1 1/2 tbsp each).',
  'When eating, pour the dressing over and toss. Top with the rest of the sesame seeds.',
  'Taste the dressing: it should be tangy and a bit sweet. Add a pinch of salt or 1 tsp more honey to taste.'],
 fix=['Watery slaw: it was dressed too early. Keep the dressing separate and drain any liquid.','Too sharp: add 1 tsp honey or 1 tbsp oil.'],
 swap='Allergy to sesame: leave out the seeds and use 1 tbsp more canola oil. Gluten-free: use tamari. Use pre-shredded coleslaw mix to save 8 minutes.')

rec(id='V6', nombre='Chopped Cucumber-Tomato Salad (raw)', comp='verdura', fam=['MED','MEX'],
 yld=900, ing=[('cucumber','2 medium, diced',400),('tomato','1 lb Roma or cherry tomatoes, diced',400),('redonion','1/2 small, finely diced',80),('parsley','1/4 cup, chopped',15),('oil','2 tbsp',27),('lemon','2 tbsp',30),('oregano','1/2 tsp',0.8),('salt','3/4 tsp',4.5)],
 alerg=[], fr=3, fz=0, reheat='Not reheated. Eat cold. Add the dressing on the day.', act=15, tot=15, oven=None, slot='Cold',
 slot_txt='Cold prep, no heat. Prep it last, as it is the most perishable thing in the week.',
 steps=['Dice the cucumbers and tomatoes into 1/2-inch pieces. Scoop out the seedy centre of the tomatoes if they are very juicy.',
  'Finely dice the red onion. Soak it in cold water for 5 minutes, then drain, to take away the sharp bite.',
  'Mix the cucumber, tomato, onion and parsley in a bowl. Do not add the salt yet.',
  'In a jar, shake the oil, lemon juice, oregano and salt until creamy.',
  'Portion the salad into 5 containers (about 180 g each) lined with a paper towel, with the dressing in a small cup.',
  'On eating day, pour the dressing over. It should taste bright and a little salty, with crisp cucumber.'],
 fix=['Soggy: salt and dressing draw out water. Dress only at the last minute.','Bland tomatoes: add a pinch of sugar and extra lemon. Cherry tomatoes hold up better than big ones.'],
 swap='Add 1/2 cup crumbled feta or a can of chickpeas for a heartier salad (macros change). Use bell pepper if cucumbers are out of season.')
